<script lang="ts">
 import {auth} from '#lib/auth.svelte.ts';
 import {anyApi} from 'convex/server';
 let rows=$state<any[]|null>(null),allowed=$state(false),checked=$state(false),busy=$state(false),error=$state(''),source=$state(''),search=$state(''),status=$state('all');
 const filtered=$derived((rows??[]).filter(row=>(status==='all'||row.mode===status)&&`${row.version} ${row.sport} ${row.league} ${row.artifact.scope??'full'}`.toLowerCase().includes(search.toLowerCase())));
 $effect(()=>{const client=auth.client;allowed=false;checked=auth.status!=='loading'&&!client;rows=null;if(!client)return;return client.onUpdate(anyApi.admin.status,{},r=>{allowed=r.isSuperAdmin===true;checked=true;},()=>{checked=true;error='Access verification failed.';});});
 $effect(()=>{const client=auth.client;if(!allowed||!client)return;return client.onUpdate(anyApi.models.list,{},r=>{rows=r;error='';},()=>error='Model registry unavailable. Reload this workspace to retry.');});
 async function register(){if(!auth.client)return;busy=true;error='';try{await auth.client.mutation(anyApi.models.register,{artifact:JSON.parse(source)});source='';}catch(e){error=e instanceof Error?e.message:'Import failed.';}finally{busy=false;}}
 async function change(id:any,retire=false){if(!auth.client)return;busy=true;error='';try{await auth.client.mutation(retire?anyApi.models.retire:anyApi.models.shadowActivate,{id});}catch(e){error=e instanceof Error?e.message:'Update failed.';}finally{busy=false;}}
</script>
<svelte:head><title>Model registry · PuntersEdge</title><meta name="robots" content="noindex,nofollow"/></svelte:head>
<section class="space-y-6">
 <header class="surface p-6 sm:p-8"><p class="text-xs font-semibold uppercase tracking-widest text-model">🧮 Model governance</p><h1 class="mt-3 text-3xl font-bold sm:text-5xl">Model registry</h1><p class="mt-3 max-w-2xl text-sm leading-relaxed text-haze">Manage versioned candidates and their serving state. Shadow activation updates mapped forecasts; it does not approve betting recommendations.</p></header>
 {#if error}<div role="alert" class="rounded-2xl border border-loss/40 bg-loss/10 p-4"><h2 class="font-semibold text-loss">The operation could not complete</h2><p class="mt-2 break-words text-sm">{error}</p></div>{/if}
 {#if !checked}<div class="workspace-state" role="status"><h2>Verifying access</h2><p>Connecting to your administrator account.</p></div>{:else if !allowed}<div class="workspace-state"><h2>Administrator access required</h2><p>Sign in with the authorized administrator account to manage models.</p><a class="btn-primary mt-4" href="/login?next=/admin/models">Sign in</a></div>{:else}
 <div class="grid gap-3 sm:grid-cols-3">{#each [['All candidates',rows?.length],['Serving',rows?.filter(r=>r.mode==='active').length],['Retired',rows?.filter(r=>r.mode==='retired').length]] as [label,count]}<div class="surface p-5"><p class="text-sm text-haze">{label}</p><p class="mt-2 font-display text-3xl font-bold">{count??'—'}</p></div>{/each}</div>
 <details class="surface p-5"><summary class="cursor-pointer py-2 font-semibold">📥 Import a model candidate</summary><p class="mt-3 text-sm text-haze">Provide a fitted artifact with a training cutoff, competition, scope and mapped team parameters. Imports are validated on the server.</p><label for="artifact" class="mt-5 block text-sm font-semibold">Artifact JSON</label><textarea id="artifact" bind:value={source} rows="10" class="mt-2 w-full rounded-xl border border-line bg-ink p-4 font-mono text-sm" spellcheck="false" placeholder="Paste the versioned model artifact"></textarea><button class="btn-primary mt-3" disabled={busy||!source.trim()} onclick={register}>{busy?'Processing…':'Import candidate'}</button></details>
 <section class="space-y-4"><div class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="text-xl font-bold">Candidate inventory</h2><p class="mt-1 text-sm text-haze">{rows?`${filtered.length} matching candidates`:'Loading registry…'}</p></div><div class="flex w-full flex-wrap gap-2 sm:w-auto"><label class="flex min-w-0 flex-1 flex-col gap-1 text-xs text-haze">Search<input bind:value={search} type="search" placeholder="Version, sport or league" class="min-h-11 rounded-xl border border-line bg-deep px-3 text-sm"/></label><label class="flex flex-col gap-1 text-xs text-haze">State<select bind:value={status} class="min-h-11 rounded-xl border border-line bg-deep px-3 text-sm"><option value="all">All states</option><option value="active">Serving</option><option value="shadow">Candidate</option><option value="retired">Retired</option></select></label></div></div>
 {#if !rows}<div class="workspace-state" role="status"><h2>Loading model records</h2><p>Waiting for the protected registry subscription.</p></div>{:else}{#each filtered as row(row._id)}<article class="surface p-5 sm:p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div class="min-w-0"><p class="text-xs font-semibold uppercase tracking-wider text-haze">{row.sport} · {row.artifact.scope??'full game'}</p><h3 class="mt-2 break-words text-lg font-bold">{row.version}</h3><p class="mt-1 text-sm text-haze">{row.league}</p></div><span class="rounded-full border border-line bg-raised px-3 py-1.5 text-xs font-semibold">{row.mode==='active'?'Serving':row.mode} · {row.approved?'Approved':'Unvalidated'}</span></div><dl class="mt-5 grid gap-3 border-y border-line py-4 sm:grid-cols-2"><div><dt class="text-xs text-haze">Training games</dt><dd class="mt-1 font-semibold">{row.artifact.trainingCount??'Not supplied'}</dd></div><div><dt class="text-xs text-haze">Training cutoff</dt><dd class="mt-1 break-words text-sm">{row.artifact.trainedThrough}</dd></div></dl><div class="mt-4 flex flex-wrap gap-3"><button class="btn-primary" disabled={busy||row.mode==='active'} onclick={()=>change(row._id)}>{row.mode==='active'?'Currently serving':'Use for shadow forecasts'}</button><button class="btn-ghost text-loss" disabled={busy||row.mode==='retired'} onclick={()=>change(row._id,true)}>Retire candidate</button></div></article>{:else}<div class="workspace-state"><h2>{rows.length?'No matching candidates':'No models imported yet'}</h2><p>{rows.length?'Try another search or state filter.':'Import a fitted, versioned artifact to begin prospective evaluation.'}</p></div>{/each}{/if}
 </section>{/if}
</section>
